// spec: specs/data-requests-reauth.md (1.1) · кейс DR-01 · запасной путь (MCP playwright-test отключён)
// seed: tests/seed.parent-b.spec.ts
// До окна «אימות זהות» и «ביטול». Пароль не вводится, запрос не отправляется (записи обрываются в браузере).
import { test, expect } from '@playwright/test';
import { PARENT_B, T, blockDataRequestWrites, cancelReauth, chip, expectReauthDialog, openForm, sendButton, visibleText } from './data-requests.helpers';

test.use({ storageState: PARENT_B, viewport: { width: 1280, height: 800 } });

test.describe('Запросы данных — «אימות זהות» перед удалением', () => {
  test('Удаление данных ребёнка: «שליחת הבקשה» открывает «אימות זהות», без POST; «ביטול» сохраняет форму @desktop @prod-safe #c3aa39', async ({ page }) => {
    const writes = await blockDataRequestWrites(page);
    await openForm(page);

    await chip(page, 'QA-B1').click();
    await chip(page, T.kindDelete).click();
    await expect(page.getByText(T.deleteChildHint).filter({ visible: true }).first()).toBeVisible();
    const note = 'QA-AUTO-c3aa39 — לא לשלוח';
    await page.getByPlaceholder(T.detailsPlaceholder).filter({ visible: true }).first().fill(note);

    await sendButton(page).click();

    // «מה רצוי»: «בקשת מחיקה דורשת אימות זהות»
    await expectReauthDialog(page);
    expect(writes, `до пароля не было записи запроса: ${JSON.stringify(writes)}`).toEqual([]);

    await cancelReauth(page);

    // Форма на месте, выбранное действие и текст сохранены; запрос не создан
    await expect(page).toHaveURL(/\/privacy\/data-request/);
    await expect(visibleText(page, T.formTitle)).toBeVisible();
    await expect(page.getByText(T.deleteChildHint).filter({ visible: true }).first()).toBeVisible();
    await expect(page.getByPlaceholder(T.detailsPlaceholder).filter({ visible: true }).first()).toHaveValue(note);
    await expect(sendButton(page)).toBeVisible();
    expect(writes, 'после «ביטול» запрос не создан').toEqual([]);
  });
});
